<?php require 'config.php';auth();if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: inquiries.php');exit;}check_token();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)){flash('Enter a name and valid email address.','error');header('Location: inquiries.php');exit;}$s=db()->prepare('INSERT INTO inquiries(name,email,phone,subject,message) VALUES(?,?,?,?,?)');$s->execute([$name,$email,trim($_POST['phone']??'')?:null,trim($_POST['subject']??'')?:null,trim($_POST['message']??'')?:null]);flash('Inquiry saved successfully.');header('Location: inquiries.php');exit;
